<?php
 namespace App\Library; use Illuminate\Support\Facades\Log; class CurlRequest { public static function curl($url, $method = 0, $post_data = '', $headers = [], $timeout = 5, &$cookie = false, &$httpCode = false, &$error = false) { if (!isset($headers['Accept']) && !isset($headers['accept'])) { $headers['Accept'] = "*/*"; } if (!isset($headers['Referer']) && !isset($headers['referer'])) { $headers['Referer'] = $url; } if (!isset($headers['Content-Type']) && !isset($headers['content-type'])) { $headers['Content-Type'] = "application/x-www-form-urlencoded"; } if (!isset($headers['User-Agent']) && !isset($headers['user-agent'])) { $headers['User-Agent'] = "Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/55.0.2883.87 Safari/537.36"; } if ($cookie !== false) { $headers['Cookie'] = $cookie; } $sendHeaders = array(); foreach ($headers as $headerName => $headerVal) { $sendHeaders[] = $headerName . ': ' . $headerVal; } $sendHeaders[] = 'Expect:'; $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, true); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 2); curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true); curl_setopt($ch, CURLOPT_MAXREDIRS, 3); if ($method == 1) { curl_setopt($ch, CURLOPT_CUSTOMREQUEST, 'POST'); curl_setopt($ch, CURLOPT_POST, 1); if ($post_data !== '') { curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data); curl_setopt($ch, CURLOPT_POSTREDIR, 3); } } if (defined('MY_PROXY')) { $proxy = MY_PROXY; $proxy_type = CURLPROXY_HTTP; if (strpos($proxy, 'http://') || strpos($proxy, 'https://')) { $proxy = str_replace('http://', $proxy, $proxy); $proxy = str_replace('https://', $proxy, $proxy); $proxy_type = CURLPROXY_HTTP; } elseif (strpos($proxy, 'socks4://')) { $proxy = str_replace('socks4://', $proxy, $proxy); $proxy_type = CURLPROXY_SOCKS4; } elseif (strpos($proxy, 'socks4a://')) { $proxy = str_replace('socks4a://', $proxy, $proxy); $proxy_type = CURLPROXY_SOCKS4A; } elseif (strpos($proxy, 'socks5://')) { $proxy = str_replace('socks5://', $proxy, $proxy); $proxy_type = CURLPROXY_SOCKS5_HOSTNAME; } curl_setopt($ch, CURLOPT_PROXY, $proxy); curl_setopt($ch, CURLOPT_PROXYTYPE, $proxy_type); if (defined('MY_PROXY_PASS')) curl_setopt($ch, CURLOPT_PROXYUSERPWD, MY_PROXY_PASS); } curl_setopt($ch, CURLOPT_TIMEOUT, $timeout); curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, $timeout); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_HEADER, 1); curl_setopt($ch, CURLOPT_HTTPHEADER, $sendHeaders); $response = curl_exec($ch); if (curl_errno($ch)) { $error = curl_error($ch); curl_close($ch); return null; } $headerSize = curl_getinfo($ch, CURLINFO_HEADER_SIZE); if ($httpCode) { $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE); } $header = substr($response, 0, $headerSize); $body = substr($response, $headerSize); curl_close($ch); if ($cookie !== false) { $headers = explode("\r\n", $header); $returnCookie = ''; foreach ($headers as $header) { if (strtolower(substr($header, 0, 11)) === 'set-cookie:') { $header = 'Set-Cookie:' . substr($header, 11); if (strpos($header, 'Set-Cookie') !== false) { if (strpos($header, ';') !== false) { $returnCookie = $returnCookie . trim(Helper::str_between($header, 'Set-Cookie:', ';')) . ";"; } else { $returnCookie = $returnCookie . trim(str_replace('Set-Cookie:', '', $header)) . ";"; } } } } $cookie = self::combineCookie($cookie, $returnCookie); } return $body; } public static function get($url, $headers = [], $timeout = 5, &$cookie = false) { return self::curl($url, 0, '', $headers, $timeout, $cookie); } public static function post($url, $post_data = '', $headers = [], $timeout = 5, &$cookie = false) { return self::curl($url, 1, $post_data, $headers, $timeout, $cookie); } public static function download($url, $filepath, $progress = false) { $fp = fopen($filepath, 'w+'); if (!$fp) { throw new \Exception("cant open file: " . $filepath); } $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_FILE, $fp); if ($progress) { curl_setopt($ch, CURLOPT_PROGRESSFUNCTION, function ( $resource, $download_size, $downloaded, $upload_size, $uploaded ) { if ($download_size > 0) echo("\r    download: " . sprintf('%.2f', $downloaded / $download_size * 100) . '%'); } ); curl_setopt($ch, CURLOPT_NOPROGRESS, false); } curl_setopt($ch, CURLOPT_HEADER, 0); curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/55.0.2883.87 Safari/537.36'); if (defined('MY_PROXY')) { $proxy = MY_PROXY; $proxy_type = CURLPROXY_HTTP; if (strpos($proxy, 'http://') || strpos($proxy, 'https://')) { $proxy = str_replace('http://', $proxy, $proxy); $proxy = str_replace('https://', $proxy, $proxy); $proxy_type = CURLPROXY_HTTP; } elseif (strpos($proxy, 'socks4://')) { $proxy = str_replace('socks4://', $proxy, $proxy); $proxy_type = CURLPROXY_SOCKS4; } elseif (strpos($proxy, 'socks4a://')) { $proxy = str_replace('socks4a://', $proxy, $proxy); $proxy_type = CURLPROXY_SOCKS4A; } elseif (strpos($proxy, 'socks5://')) { $proxy = str_replace('socks5://', $proxy, $proxy); $proxy_type = CURLPROXY_SOCKS5_HOSTNAME; } curl_setopt($ch, CURLOPT_PROXY, $proxy); curl_setopt($ch, CURLOPT_PROXYTYPE, $proxy_type); if (defined('MY_PROXY_PASS')) curl_setopt($ch, CURLOPT_PROXYUSERPWD, MY_PROXY_PASS); } curl_exec($ch); if (curl_errno($ch)) { curl_close($ch); throw new \Exception("curl_error: " . curl_error($ch)); } curl_close($ch); return true; } public static function combineCookie($old, $new) { $old_array = explode(';', $old); $new_array = explode(';', $new); foreach ($old_array as $line) { if (self::cookieIsExists($new_array, self::cookieGetName($line)) == false) { array_push($new_array, $line); } } $newCookie = ''; foreach ($new_array as $line) { if (substr($line, -8, 8) != '=deleted' && strlen($line) > 1) { $newCookie .= $line . '; '; } } return substr($newCookie, 0, strlen($newCookie) - 1); } public static function cookieGetName($singleCookie) { $index = strpos($singleCookie, '='); return substr($singleCookie, 0, $index); } public static function cookieGetValue($singleCookie) { $index = strpos($singleCookie, '='); $b = substr($singleCookie, $index + 1, strlen($singleCookie) - $index); return $b; } public static function cookieGet($cookie, $name, $withName = false) { $cookie = str_replace(' ', '', $cookie); if (substr($cookie, -1, 1) != ';') { $cookie = ';' . $cookie . ';'; } else { $cookie = ';' . $cookie; } $t = Helper::str_between($cookie, ';' . $name . '=', ';'); if (!$withName || $t == '') { return $t; } else { return $name . '=' . $t; } } private static function cookieIsExists($allCookie, $searchName) { foreach ($allCookie as $line) { if (self::cookieGetName($line) == $searchName) { return true; } } return false; } function test() { $b = self::combineCookie('a=1;b=2;c=3', 'c=5'); var_dump($b); } } 